def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    from datetime import time as _time
    if value is None:
        return None
    if not isinstance(value, _time):
        raise TypeError(f"Expected datetime.time, got {type(value)!r}")
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # Validate that the input has the required attributes.
    try:
        lat = value.lat
        lon = value.lon
        time = value.time
    except AttributeError:
        raise TypeError(
            "dehydrate_point expects a Point-like object with lat, lon, and time attributes"
        )

    # Convert the time attribute to an ISO‑formatted string if possible.
    if hasattr(time, "isoformat"):
        time_str = time.isoformat()
    else:
        # Fallback to string representation.
        time_str = str(time)

    return {"lat": lat, "lon": lon, "time": time_str}

