def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Collect all values from the record in insertion order
    try:
        all_vals = [val for _, val in self.iteritems()]
    except AttributeError:
        raise AttributeError("The object does not support iteration over items (missing iteritems method).")

    # If no keys specified, return all values
    if not keys:
        return all_vals

    # Build a lookup dictionary for key based access
    key_val_map = {k: v for k, v in self.iteritems()}

    result = []
    for k in keys:
        # Determine if key is an index or a key
        if isinstance(k, int):
            # handle negative indices as Python lists
            if k < 0 or k >= len(all_vals):
                raise IndexError(f"Index {k} out of range when retrieving values.")
            result.append(all_vals[k])
        else:
            try:
                result.append(key_val_map[k])
            except KeyError:
                raise KeyError(f"Key {k!r} not found in record.")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Prepare the base mapping of field names to values.
    if hasattr(self, "_data") and isinstance(self._data, dict):
        base = dict(self._data)
    elif hasattr(self, "_keys") and hasattr(self, "_values"):
        base = dict(zip(self._keys, self._values))
    else:
        raise AttributeError("Record object does not expose '_data', '_keys' and '_values' attributes.")

    # If no specific keys requested, return a shallow copy of the whole record.
    if not keys:
        return dict(base)

    result = {}
    for key in keys:
        # Numeric index case.
        if isinstance(key, int):
            if not (0 <= key < len(self._values)):
                raise IndexError(f"Index {key} out of bounds for record")
            name = self._keys[key]
            value = self._values[key]
            result[name] = value
            continue

        # String key case.
        if isinstance(key, str):
            if key in base:
                result[key] = base[key]
            else:
                # Key not present in the record – insert with None.
                result[key] = None
            continue

        # Unsupported key type – de‑know handling as an error.
        raise TypeError(f"Unsupported key type {type(key).__name__} (must be int or str)")
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    data = self.data
    if len(data) < 2:
        raise ValueError("Not enough bytes to pop 16-bit value")
    end_bytes = data[-2:]
    del data[-2:]
    return int.from_bytes(end_bytes, "big")

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
