        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    mode_val = mode.upper() if mode else "WRITE"
    if mode_val not in ("READ", "WRITE"):
        raise ValueError("mode must be either 'READ' or 'WRITE'")
    params = {"mode": mode_val}

    # Bookmarks
    if bookmarks is not None:
        try:
            bp_list = list(bookmarks)
        except Exception:
            raise ValueError("bookmarks must be an iterable")
        if bp_list:
            params["bookmarks"] = bp_list

    # Metadata
    if metadata is not None:
        if not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary")
        params["metadata"] = metadata

    # Timeout
    if timeout is not None:
        try:
            timeout_val = float(timeout)
        except Exception:
            raise ValueError("timeout must be a numeric value")
        params["timeout"] = timeout_val

    # Database
    if db is not None:
        params["db"] = str(db)

    # Impersonated user
    if imp_user is not None:
        params["impersonated_user"] = str(imp_user)

    # Register hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
        # Assume the session holds a dict of hooks
        if not hasattr(self, "_dehydration_hooks"):
            self._dehydration_hooks = {}
        self._dehydration_hooks.update(dehydration_hooks)

    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")
        if not hasattr(self, "_hydration_hooks"):
            self._hydration_hooks = {}
        self._hydration_hooks.update(hydration_hooks)

    # Append the BEGIN message to the outgoing queue
    msg = {"type": "BEGIN", "params": params}
    if hasattr(self, "_send_message"):
        self._send_message("BEGIN", params)
    else:
        # Fallback to direct queue manipulation
