def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import functools, warnings

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)

        # Append a deprecation notice to the original docstring, if any.
        original_doc = func.__doc__ or ""
        deprecation_note = f"\n\n*Deprecated:* {message}"
        wrapper.__doc__ = original_doc + deprecation_note
        return wrapper

    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """Poor man's version comparison.

    It splits the input string on periods and extracts the leading integer
    from each segment. Non‑numeric suffixes are ignored. The function
    returns a tuple of integers that can be compared lexicographically.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")

    segments = s.split(".")
    nums: list[int] = []

    for seg in segments:
        if not seg:
            continue
        num_str = ""
        for ch in seg:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            try:
                nums.append(int(num_str))
            except ValueError:
                # Skip any segment that doesn't start with a valid integer
                continue

    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError("maxsize must be a positive integer")
    def decorator(func):
        cache = {}
        counts = {}
        @functools.wraps(func)
        def make_key(args, kwargs):
            kwitems = tuple(sorted(kwargs.items()))
            if typed:
                key_args = tuple((a, type(a)) for a in args)
                key_kwargs = tuple((k, (v, type(v))) for k, v in kwitems)
            else:
                key_args = args
                key_kwargs = kwitems
            return (key_args, key_kwargs)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                counts[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # evict least‑frequently used key
                # in case of ties, evict arbitrary one among them
                min_count = None
                key_to_remove = None
                for k in cache:
                    c = counts.get(k, 0)
                    if min_count is None or c < min_count:
                        min_count = c
                        key_to_remove = k
                if key_to_remove is not None:
                    del cache[key_to_remove]
                    del counts[key_to_remove]
            cache[key] = result
            counts[key] = 1
            return result

        return wrapper
    return decorator

