def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all handlers attached to the root logger
        for handler in root.handlers[:]:
            root.removeHandler(handler)
            try:
                handler.close()
            except Exception:
                pass
        # Reconfigure root logger with default settings
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )
    except Exception:
        # If resetting fails, fall back to a minimal configuration
        try:
            logging.basicConfig(
                level=logging.WARNING,
                format='%(levelname)s: %(message)s'
            )
        except Exception:
            pass

