def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("'classes' must be a sequence of types")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"item {cls!r} is not a type")
        # If an existing base is an ancestor of this class, skip it
        if any(issubclass(cls, base) for base in result):
            continue
        # Remove any bases that are descendants of this class
        result = [base for base in result if not issubclass(base, cls)]
        result.append(cls)
    return result

