def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to numpy arrays for vectorised operations
    bins_arr = np.asarray(bins)
    # Handle the edges input: can be a single array or a sequence for 2‑D histograms
    if isinstance(edges, (list, tuple)):
        # 1‑D case (len(edges) == 1) or 2‑D case (len(edges) == 2)
        if len(edges) == 1:
            e = np.asarray(edges[0])
            widths = np.diff(e)
            if bins_arr.shape != widths.shape:
                raise ValueError("Shape of bins does not match edge widths.")
            return np.sum(bins_arr * widths)
        elif len(edges) == 2:
            e0 = np.asarray(edges[0])
            e1 = np.asarray(edges[1])
            w0 = np.diff(e0)
            w1 = np.diff(e1)
            if bins_arr.shape != (len(w0), len(w1)):
                raise ValueError("Shape of bins does not match 2‑D edge widths.")
            # Compute outer product of widths to get bin areas
            areas = np.outer(w0, w1)
            return np.sum(bins_arr * areas)
        else:
            raise ValueError("Edges must be a sequence of 1 or 2 arrays for 1‑D or 2‑D histograms.")
    else:
        # Assume 1‑D edges provided directly
        e = np.asarray(edges)
        widths = np.diff(e)
        if bins_arr.shape != widths.shape:
            raise ValueError("Shape of bins does not match edge widths.")
        return np.sum(bins_arr * widths)

