def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coordinate is array-like
    coord = np.asarray(coord)
    # Validate existence of edges and histogram data
    if not hasattr(self, 'edges'):
        raise AttributeError("Histogram object must have an 'edges' attribute.")
    if not hasattr(self, 'hist'):
        raise AttributeError("Histogram object must have a 'hist' attribute.")

    # Convert edges to a list (support single or multiple dimensions)
    if isinstance(self.edges, np.ndarray):
        # Assume 1D edges stored as a 1D array
        edges_list = [self.edges]
    else:
        edges_list = list(self.edges)

    ndim = len(edges_list)

    # If coord is scalar and histogram is 1D, wrap it
    if ndim == 1 and coord.ndim == 0:
        coord = coord.reshape(1)

    if coord.shape[-1] != ndim:
        raise ValueError(f"Coordinate dimensionality {coord.shape[-1]} does not match histogram dimensions {ndim}.")

    # Find bin indices for each dimension
    bin_indices = []
    for dim, x in enumerate(coord.T):
        edges = edges_list[dim]
        # Find the right bin using searchsorted; get index of left edge
        bin_idx = np.searchsorted(edges, x, side='right') - 1
        # Check bounds: ignore if out of range
        if np.any(bin_idx < 0) or np.any(bin_idx >= len(edges) - 1):
            return  # Coordinates outside histogram edges are ignored
        bin_indices.append(bin_idx)

    # Reduce list of arrays to a tuple index
    idx = tuple(b.flatten() for b in bin_indices)

    # Accumulate weight
    try:
        self.hist[idx] += weight
    except Exception:
        # Fallback for hist stored in a dictionary
        if isinstance(self.hist, dict):
            for key in idx:
                self.hist[key] = self.hist.get(key, 0) + weight
        else:
            raise ValueError("Unsupported histogram storage format.")
    return self

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
