        # If the schema indicates a nested mapping, recurse
        if isinstance(sub_schema, dict):
            # Initialize nested dict in last_applied_manifest if missing
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            elif not isinstance(last_applied_manifest[key], dict):
                # If an existing value is not a dict, overwrite it
                last_applied_manifest[key] = {}
            sub_response = response[key]
            if not isinstance(sub_response, dict):
                raise KeyError(
                    f"Expected dict for field '{key}' in response, "
                    f"but got {type(sub_response).__name__}"
                )
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, sub_response
            )
        else:
            # Primitive field: set if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure application has a spec attribute
    if not hasattr(app, "spec"):
        return

    # Retrieve the manifest (list or dict of Kubernetes resources)
    manifest = getattr(app.spec, "manifest", None)
    if manifest is None:
        return

    # Ensure there is a dictionary to store observer schemas
    observer_schema = getattr(app.spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(app.spec, "observer_schema", observer_schema)

    # Helper function to generate a simple default schema
    def _default_schema():
        # A minimal placeholder schema: allow any object
        return {"type": "object"}

    # Iterate over the resources in the manifest
    if isinstance(manifest, dict):
        # Assume key is a resource name or identifier
        items = manifest.items()
    elif isinstance(manifest, list):
        # List of resource dicts
        items = enumerate(manifest)
    else:
        # Unsupported type
        return

    for key, resource in items:
        # Attempt to extract a unique name for the resource
        res_name = None
        if isinstance(resource, dict):
            res_name = resource.get("metadata", {}).get("name")
        if not res_name:
            # Fallback to the key/index if no metadata name
            res_name = key
        if not res_name:
            continue

        # Skip if a custom schema already exists
        if res_name in observer_schema:
            continue

        # Assign the default schema
        observer_schema[res_name] = _default_schema()

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        result = self._validate(path)
        if hasattr(result, 'errors') and result.errors:
            return False
        if isinstance(result, (list, tuple)):
            return not result
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Try to get a log-like attribute
        log = getattr(self, 'log', None)
        if log is None:
            log = getattr(self, 'messages', None)
        if log is None:
            return f"{prefix}<no log available>"
        # Convert log to a readable string
        if isinstance(log, (list, tuple)):
            lines = [str(item) for item in log]
            log_str = "\n".join(lines)
        else:
            log_str = str(log)
        return f"{prefix}{log_str}"
    except Exception as e:
        return f"{prefix}<error retrieving log: {e}>"

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    errors = []

    # Verify that each file in the manifest has a known digest
    for file in manifest_files:
        digests = self.analyzed_files.get(file)
        if not digests:
            errors.append(f"Manifest file '{file}' not found in analyzed files.")
            continue
        # Use the first digest as the expected one (assuming one digest per file)
        digest = digests[0]
        if digest not in digests_used:
            errors.append(f"Digest '{digest}' for file '{file}' is not marked as used.")

    # Verify that every used digest exists among the analyzed files
    known_digests = { d for digs in self.analyzed_files.values() for d in digs }
    for digest in digests_used:
        if digest not in known_digests:
            errors.append(f"Used digest '{digest}' not found among analyzed files.")

    if errors:
        raise ValueError("\n".join(errors))

    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type of validator
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # If a version field exists, ensure that prior's version is older
    if hasattr(self, "version") and hasattr(prior, "version"):
        try:
            if prior.version >= self.version:
                raise ValueError(
                    f"prior.version ({prior.version!r}) is not older than current version ({self.version!r})"
                )
        except TypeError:
            # Fall back on string comparison if the objects are not natively comparable
            if str(prior.version) >= str(self.version):
                raise ValueError(
                    f"prior.version ({prior.version!r}) is not older than current version ({self.version!r})"
                )

    # Define a set of attributes that are considered metadata and not part of the core inventory
    metadata_attrs = {"timestamp", "created_at", "updated_at", "metadata", "id"}

    # Determine the set of relevant attributes present in each object
    self_attrs = {k for k in vars(self).keys() if k not in metadata_attrs}
    prior_attrs = {k for k in vars(prior).keys() if k not in metadata_attrs}

    # A prior inventory must not introduce new attributes that are missing in the current one
    missing_in_current = prior_attrs - self_attrs
    if missing_in_current:
        raise ValueError(
            f"prior inventory has attributes missing in the current inventory: {missing_in_current}"
        )

    # For every shared attribute, enforce monotonic or unchanged behaviour
    for attr in prior_attrs:
        curr_val = getattr(self, attr)
        prev_val = getattr(prior, attr)

        # Numeric values should not decrease
        if isinstance(curr_val, (int, float)):
            if prev_val > curr_val:
                raise ValueError(
                    f"Numeric attribute '{attr}' decreased from {prev_val} to {curr_val}"
                )
        else:
            # For non-numeric types, expect exact equality unless the type supports
            # an update pattern (e.g., lists where new elements can be appended).
            # Here we enforce strict equality for simplicity.
            if curr_val != prev_val:
                raise ValueError(
                    f"Attribute '{attr}' changed between versions (prior={prev_val!r}, current={curr_val!r})"
                )

    # If all checks pass, return a truthy value indicating a valid prior
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a mapping (dict)")

    # If the block is empty, nothing to validate
    if not fixity:
        return True

    for file_path, entry in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"Fixity references unknown file: {file_path}")

        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry for {file_path} must be a mapping")

        # Basic sanity checks: at least one of algorithm or value present
        if not any(k in entry for k in ("algorithm", "value")):
            raise ValueError(f"Fixity entry for {file_path} must contain 'algorithm' or 'value'")

        # If present, algorithm should be a string
        if "algorithm" in entry and not isinstance(entry["algorithm"], str):
            raise ValueError(f"'algorithm' for {file_path} must be a string")

        # If present, value should be a string (most common case)
        if "value" in entry and not isinstance(entry["value"], str):
            raise ValueError(f"'value' for {file_path} must be a string")

    return True

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path '{path}' does not exist.")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"Path '{path}' is not a directory.")
        entries = os.listdir(path)
        files = [os.path.abspath(os.path.join(path, e)) for e in entries if os.path.isfile(os.path.join(path, e))]
        return sorted(files)
    except OSError as exc:
        raise exc from None

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate inputs
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("file_path must be a non-empty string.")
    if not isinstance(lang, str) or not lang:
        raise ValueError("lang must be a non-empty string.")

    try:
        # Separate directory, base name, and extension
        dir_name, base_name = os.path.split(file_path)
        name, ext = os.path.splitext(base_name)

        # Insert language suffix before the extension
        new_name = f"{name}-{lang}{ext}"
        new_path = os.path.join(dir_name, new_name)

        return new_path
    except Exception as exc:
        # If logger is present on the instance, log the exception
        logger = getattr(self, "_logger", None)
        if logger:
            logger.exception("Error adding rendition for '%s': %s", file_path, exc)
        raise  # re-raise the original exception for upstream handling

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            return zf.namelist()
    except Exception:
        return []

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    if content is None:
        return content
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            # Try XPath evaluation first (lxml, etree, etc.)
            matches = node.xpath(xpath) if hasattr(node, "xpath") else None
        except Exception:
            matches = None
        # If XPath didn't work, try CSS selector as fallback (BeautifulSoup)
        if matches is None:
            try:
                matches = node.select(xpath) if hasattr(node, "select") else None
            except Exception:
                matches = None
        # Return the first matched element if any
        if matches:
            return matches[0]
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Initial indentation level. Negative values are treated as zero.
    debug : bool, optional
        If True, include the object's class name and increase indentation for readability.

    Returns
    -------
    str
        A human‑readable, indented string representation of the object.
    """
    # Ensure a non‑negative indentation level
    indent = max(indent, 0)
    visited = set()

    def _pretty(obj, level):
        """
        Recursively build a formatted string for *obj* at the given indentation *level*.
        """
        if id(obj) in visited:
            return '...'
        visited.add(id(obj))

        # Basic data types
        if isinstance(obj, (bool, int, float, type(None))):
            return str(obj)
        if isinstance(obj, str):
            return repr(obj)

        # Containers
        if isinstance(obj, (list, tuple, set)):
            open_char, close_char = ('[', ']') if isinstance(obj, list) \
                else ('(', ')') if isinstance(obj, tuple) else ('{', '}')
            items = [_pretty(item, level + 1) for item in obj]
            ind = '  ' * level
            inner = ',\n'.join(f"{ind}  {item}" for item in items)
            return f"{open_char}\n{inner}\n{ind}{close_char}"

        if isinstance(obj, dict):
            items = [f"{_pretty(k, level + 1)}: {_pretty(v, level + 1)}"
                     for k, v in obj.items()]
            ind = '  ' * level
            inner = ',\n'.join(f"{ind}  {item}" for item in items)
            return f"{{\n{inner}\n{ind}}}"

        # Objects with __dict__
        if hasattr(obj, "__dict__"):
            return _pretty(vars(obj), level)

        # Fallback: use repr
        return repr(obj)

    try:
        if debug:
            cls_name = f"{self.__class__.__name__}:" if hasattr(self, "__class__") else ""
            ind = '  ' * indent
            body = _pretty(self, indent + 1)
            return f"{ind}{cls_name}\n{body}"
        else:
            return _pretty(self, indent)
    except Exception as exc:
        return f"<Error during pretty formatting: {exc}>"

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise ValueError('namefunc must be a callable')
    import sys
    def inner_func(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            raise RuntimeError('Error calling the wrapped function: {}'.format(exc))
        # If running under Python 3, return the result unchanged
        if sys.version_info[0] >= 3:
            return result
        # Python 2: ensure the result is a byte string
        try:
            text_type = unicode  # pylint: disable=redefined-builtin
        except NameError:
            # Shouldn't happen on Python 2, but guard anyway
            return result
        if isinstance(result, text_type):
            try:
                return result.encode('utf-8')
            except Exception as exc:
                raise ValueError('Failed to encode unicode result to bytes: {}'.format(exc))
        elif isinstance(result, (bytes, str)):
            # Already a byte string, just return it
            return result
        else:
            # For non-string results, just return as-is
            return result
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Attempt to use importlib.metadata (Python 3.8+)
        from importlib.metadata import distributions
        versions = {}
        for dist in distributions():
            name = dist.metadata.get("Name")
            if name:
                versions[name] = dist.version
        # If no distributions found, fall back to default
        if not versions:
            return {"default": "unknown"}
        return versions
    except Exception:
        # Fallback for environments without importlib.metadata or on errors
        try:
            from pkg_resources import working_set
            return {entry.project_name: entry.version for entry in working_set}
        except Exception:
            return {"default": "unknown"}

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Iterable[str or Mapping]
        A sequence of text pieces. Each element can be a string or a mapping
        containing a ``content`` key. If a piece is a mapping, the value of
        ``content`` is used; otherwise the element itself is used.
    style : str
        The rendering style. Supported values are ``'plain'``, ``'html'`` and
        ``'md'`` (markdown). If ``style`` is not recognized a
        :class:`ValueError` is raised.

    Returns
    -------
    str
        The rendered string.

    Raises
    ------
    TypeError
        If ``pieces`` is not iterable or ``style`` is not a string.
    ValueError
        If an unsupported ``style`` is requested.
    """
    # Basic validation
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")

    if pieces is None:
        pieces = []

    try:
        # Ensure we can iterate over pieces
        iter(pieces)
    except Exception as exc:
        raise TypeError(f"pieces must be iterable, got {type(pieces).__name__}") from exc

    def _get_text(piece):
        """Return the textual representation of a piece."""
        if isinstance(piece, dict):
            return str(piece.get("content", ""))
        return str(piece)

    rendered_parts = [_get_text(p) for p in pieces]

    if style == "plain":
        return "\n".join(rendered_parts)

    elif style == "html":
        import html
        escaped = [html.escape(part) for part in rendered_parts]
        return "<pre>\n" + "\n".join(escaped) + "\n</pre>"

    elif style == "md":
        return "\n".join(f"- {part}" for part in rendered_parts)

    else:
        raise ValueError(f"Unsupported style '{style}'. "
                         f"Supported styles: plain, html, md.")

def plus_or_dot(pieces):
    """
    Return a + if we don't already have one, else return a .
    """
    try:
        if isinstance(pieces, (list, tuple, set)):
            pieces_str = ''.join(map(str, pieces))
        elif isinstance(pieces, str):
            pieces_str = pieces
        elif pieces is None:
            pieces_str = ''
        else:
            pieces_str = str(pieces)
    except Exception:
        # If conversion fails, assume no plus present
        pieces_str = ''
    return '+' if '+' not in pieces_str else '.'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if commands is None or (isinstance(commands, str) and not commands.strip()):
        raise ValueError("No command provided to run_command")

    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        # Assume a single command string
        cmd_list = [commands]

    if args:
        if isinstance(args, (list, tuple)):
            cmd_list.extend(args)
        else:
            cmd_list.append(args)

    # Prepare environment
    run_env = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary of environment variables")
        run_env.update(env)

    # Verbosity
    if verbose:
        print("Running command:", " ".join(map(str, cmd_list)))

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT if hide_stderr else subprocess.PIPE,
            env=run_env,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        error_msg = f"Command '{' '.join(map(str, cmd_list))}' failed with exit code {exc.returncode}"
        if exc.stdout:
            error_msg += f"\nOutput:\n{exc.stdout}"
        if not hide_stderr and exc.stderr:
            error_msg += f"\nError Output:\n{exc.stderr}"
        raise RuntimeError(error_msg) from exc
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command '{cmd_list[0]}' not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run command '{' '.join(map(str, cmd_list))}': {exc}") from exc

def register_vcs_handler(vcs, method):  # type: (str, str) -> callable
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(func):
        """Store func in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = func
        return func
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Ensure we have a collection of objects to validate
        try:
            objects = list(self.storage_root.get_all_objects())
        except AttributeError:
            raise AttributeError("The storage root does not provide a 'get_all_objects' method required for validation.")

        num_objects = len(objects)
        good_objects = 0

        for obj in objects:
            is_valid = True
            try:
                # Validate the object itself if requested
                if validate_objects and hasattr(obj, 'validate'):
                    is_valid = bool(obj.validate())
                # Optionally check the object's digest
                if is_valid and check_digests and hasattr(obj, 'digest') and hasattr(obj, 'content'):
                    # In a real implementation we would compute the digest of the content and compare
                    computed_digest = obj.content and hash(obj.content)
                    if obj.digest != computed_digest:
                        is_valid = False
                        if show_warnings:
                            print(f"Digest mismatch for object {obj}: expected {obj.digest}, got {computed_digest}")
            except Exception as exc:
                # Any exception during validation is treated as a failure
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for object {obj}: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a structure to capture differences
    if not hasattr(self, "_diff_digests"):
        self._diff_digests = {}
    # Path to the root inventory (assumed to be stored in self.root_inventory_file)
    if not hasattr(self, "root_inventory_file"):
        raise AttributeError("Cannot validate without 'root_inventory_file' attribute")
    try:
        with open(self.root_inventory_file, "r", encoding="utf-8") as fh:
            root_inventory = json.load(fh)
    except FileNotFoundError:
        raise ValueError(f"Root inventory file '{self.root_inventory_file}' not found")
    except json.JSONDecodeError as err:
        raise ValueError(f"Root inventory file '{self.root_inventory_file}' is not valid JSON: {err}")

    # Validate each version directory
    for vd in version_dirs:
        inv_path = os.path.join(self.base_dir, vd, "inventory.json")
        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory file for version directory '{vd}'")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                version_inv = json.load(fh)
        except json.JSONDecodeError as err:
            raise ValueError(f"Inventory file '{inv_path}' is not valid JSON: {err}")

        # It should be a mapping of content path to digest string
        if not isinstance(version_inv, dict):
            raise ValueError(f"Inventory file '{inv_path}' should contain a mapping of content to digest")

        # Check that the inventory includes at least all entries up to this version
        # (we assume root inventory contains the complete set)
        for path, digest in version_inv.items():
            if path not in root_inventory:
                # The root inventory should contain all entries; missing ones are suspicious
                # but not necessarily an error if the version introduces new content
                # We'll ignore for now
                continue

            root_digest = root_inventory[path]
            if digest != root_digest:
                # Record the discrepancy
                self._diff_digests.setdefault(path, []).append(
                    (vd, root_digest, digest)
                )

    return self

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path:
        return "invalid path"

    try:
        if not os.path.exists(path):
            return "path not found"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # 1. check if the directory itself contains a Namaste file "0=*"
            for entry in os.listdir(path):
                full = os.path.join(path, entry)
                if os.path.isfile(full) and entry.startswith("0="):
                    return "object"

            # 2. if not, look for a subdirectory that contains a Namaste file
            for entry in os.listdir(path):
                subdir = os.path.join(path, entry)
                if os.path.isdir(subdir):
                    for subentry in os.listdir(subdir):
                        subfull = os.path.join(subdir, subentry)
                        if os.path.isfile(subfull) and subentry.startswith("0="):
                            return "root"

            # 3. If nothing matches, it is not a recognizable OCFL structure
            return "unknown directory type"

        # Should not reach here
        return "unrecognized path type"

    except Exception as exc:
        return f"error: {exc}"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (key, value) tuples')
    merged = {}
    order = []
    for key, value in nodes:
        # Keys are expected to be ScalarNode; use their .value for identity
        try:
            key_id = key.value
        except AttributeError:
            raise TypeError('key must have a .value attribute')
        if key_id in merged:
            existing = merged[key_id]
            # If both are MappingNode, deep merge
            if hasattr(existing, 'value') and hasattr(value, 'value'):
                try:
                    existing_list = existing.value
                    incoming_list = value.value
                    # Ensure both are lists
                    if isinstance(existing_list, list) and isinstance(incoming_list, list):
                        merged_list = deep_merge_nodes(existing_list + incoming_list)
                        # Construct a new MappingNode with the same tag
                        merged_node_class = existing.__class__
                        merged_node = merged_node_class(existing.tag, merged_list)
                        merged[key_id] = merged_node
                    else:
                        merged[key_id] = value
                except Exception:
                    merged[key_id] = value
            else:
                # For non-mapping or mixed types, last wins
                merged[key_id] = value
        else:
            merged[key_id] = value
            order.append(key_id)
    # Build result list preserving original first-occurrence order
    result = []
    for key_id in order:
        # Find the corresponding key node from original nodes for same key_id
        key_node = next(k for k, v in nodes if k.value == key_id)
        result.append((key_node, merged[key_id]))
    return result

