def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to determine if a node is a mapping node (has a list of entries in .value)
    def is_mapping(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    # Recursively merge two mapping nodes
    def merge_mapping(a_node, b_node):
        a_list = a_node.value
        b_list = b_node.value

        # Build a temp dict from a_list
        temp = {}
        for a_key, a_val in a_list:
            temp[a_key.value] = (a_key, a_val)

        # Merge b_list into temp
        for b_key, b_val in b_list:
            k = b_key.value
            if k in temp:
                exist_key, exist_val = temp[k]
                if is_mapping(exist_val) and is_mapping(b_val):
                    merged_child = merge_mapping(exist_val, b_val)
                    temp[k] = (exist_key, merged_child)
                else:
                    temp[k] = (exist_key, b_val)
            else:
                temp[k] = (b_key, b_val)

        # Reconstruct the merged list preserving order: first from a_list, then new keys from b_list
        merged_list = []
        for a_key, _ in a_list:
            merged_list.append((a_key, temp[a_key.value][1]))
        for b_key, _ in b_list:
            if b_key.value not in temp:
                merged_list.append((b_key, temp[b_key.value][1]))

        # Update the mapping node in place and return it
        a_node.value = merged_list
        return a_node

    result = {}
    for key_node, value_node in nodes:
        key = key_node.value if hasattr(key_node, 'value') else key_node
        if key in result:
            existing_key, existing_val = result[key]
            if is_mapping(existing_val) and is_mapping(value_node):
                merged_node = merge_mapping(existing_val, value_node)
                result[key] = (existing_key, merged_node)
            else:
                result[key] = (existing_key, value_node)
        else:
            result[key] = (key_node, value_node)

    return list(result.values())

