def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if response is None:
        raise ValueError("response must not be None")
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be greater than zero")

    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        raise RuntimeError(f"An error occurred while paging: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("All elements in 'dicts' must be dictionaries")
        for k, v in d.items():
            if not isinstance(v, (int, float)):
                raise TypeError(f"Value for key '{k}' must be numeric")
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    if not url_args:
        return url

    pattern = re.compile(r'{([^{}]+)}')

    def _replace(match):
        key = match.group(1)
        if key not in url_args:
            return match.group(0)
        value = url_args[key]
        if isinstance(value, (list, tuple)):
            value = ','.join(str(v) for v in value)
        else:
            value = str(value)
        # Encode for URL safe usage
        return urllib.parse.quote(value)

    try:
        return pattern.sub(_replace, url)
    except Exception:
        # On error, return the original URL
        return url

