def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        return vertex3tuple._vertex3tuple
    except AttributeError:
        pass
    if vertices is None:
        raise ValueError("vertices must not be None")
    try:
        verts = list(vertices)
    except TypeError:
        raise TypeError("vertices must be an iterable of points")
    n = len(verts)
    if n == 0:
        vertex3tuple._vertex3tuple = []
    else:
        triples = []
        for i in range(n):
            prev = verts[(i - 1) % n]
            curr = verts[i]
            nxt = verts[(i + 1) % n]
            triples.append((prev, curr, nxt))
        vertex3tuple._vertex3tuple = triples
    return vertex3tuple._vertex3tuple

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    # Basic type checks
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, (int, str)):
        raise TypeError("register_number must be an int or a str")
    if not isinstance(register_value, (int, str)):
        raise TypeError("register_value must be an int or a str")

    def _replace_in_dict(d):
        # Work on a list of keys to avoid RuntimeError
        for key in list(d.keys()):
            val = d[key]
            if key == register_value:
                # Replace the key with the register number
                d.pop(key)
                d[register_number] = val
                # Continue processing the value recursively
                if isinstance(val, dict):
                    _replace_in_dict(val)
                elif isinstance(val, list):
                    _replace_in_list(val)
                continue

            # Recurse into nested structures
            if isinstance(val, dict):
                _replace_in_dict(val)
            elif isinstance(val, list):
                _replace_in_list(val)

    def _replace_in_list(l):
        for item in l:
            if isinstance(item, dict):
                _replace_in_dict(item)
            elif isinstance(item, list):
                _replace_in_list(item)

    try:
        _replace_in_dict(flow_params)
    except Exception as exc:
        raise RuntimeError("Failed to replace register values") from exc

    return flow_params

