def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("input must be a class type")
    seen = set()
    stack = [cls]
    while stack:
        cur = stack.pop()
        for sub in cur.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    seen.discard(cls)
    return seen

