        files.sort()
        return ','.join(files)
    except subprocess.CalledProcessError:
        return ''

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in addrinfo:
        sockaddr = info[4]
        ip = sockaddr[0]
        # IPv4 loopback addresses: 127.0.0.0/8
        if '.' in ip:
            if ip.startswith('127.'):
                return True
        # IPv6 loopback address
        else:
            # Normalize IPv6 address to full form for comparison
            try:
                # use socket.inet_pton if available for normalization
                ip_norm = socket.inet_pton(socket.AF_INET6, ip)
            except (AttributeError, OSError):
                # Fallback: simple equality check
                pass
            if ip == '::1':
                return True
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    config_path = os.path.expanduser(config_filename)
    if os.path.isfile(config_path) and not overwrite:
        return
    # Create parent directories if needed
    try:
        os.makedirs(os.path.dirname(config_path), exist_ok=True)
    except OSError:
        # If the directory still doesn't exist, re-raise the error
        if not os.path.isdir(os.path.dirname(config_path)):
            raise
    # Write the rendered configuration to file
    try:
        with open(config_path, "w") as f:
            f.write(rendered_config)
        os.chmod(config_path, mode)
    except Exception:
        raise

def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised."""
    # Extract the name and optional default from the matcher
    if hasattr(matcher, "groupdict"):
        data = matcher.groupdict()
    else:
        data = matcher
    name = data.get("name")
    default = data.get("default")
    if name is None:
        raise ValueError("Matcher must contain a variable name.")
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise EnvironmentError(f"Environment variable {name!r} not found and no default provided.")
    return value

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        cmd = [commands]
    elif isinstance(commands, list):
        cmd = list(commands)  # make a copy
    else:
        raise TypeError("commands must be a str or a list of strings")

    if args:
        if not isinstance(args, list):
            raise TypeError("args must be a list of strings")
        cmd.extend(args)

    if verbose:
        print("Running command:", " ".join(cmd))

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
            text=True,
            check=False
        )
    except FileNotFoundError:
        raise RuntimeError(f"Command not found: {cmd[0]}")
    except Exception as e:
        raise RuntimeError(f"Failed to run command {cmd}: {e}") from e

    return result

