def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triples of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader.
    """
    try:
        # If the caller provided a specific set of nodes, we restrict the search to them;
        # otherwise we consider all subjects that appear with the given predicate.
        if roots is not None:
            subject_set = set(roots)
        else:
            # rdflib.Graph.subjects expects keyword arguments; keep None for other slots
            subject_set = set(graph.subjects(predicate=prop))
        # All objects that appear as a parent under the predicate
        object_set = set(graph.objects(predicate=prop))
        # Roots are subjects that never appear as an object (i.e., they have no parent)
        return subject_set - object_set
    except Exception:
        # In case the provided graph does not support the rdflib interface or any
        # other runtime error occurs, return an empty set.
        return set()

