def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    error_records = []

    def _recursively_resolve_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _recursively_resolve_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_recursively_resolve_env(v) for v in value]
        return value

    for fname in config_filenames:
        config_data = None
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"File not found: {fname}")

            with open(fname, 'r') as fp:
                raw = fp.read()

            if fname.endswith('.toml'):
                config_data = toml.loads(raw)
            elif fname.endswith(('.yaml', '.yml')):
                config_data = yaml.safe_load(raw)
            elif fname.endswith('.json'):
                config_data = json.loads(raw)
            else:
                # Try toml first, then yaml
                try:
                    config_data = toml.loads(raw)
                except Exception:
                    try:
                        config_data = yaml.safe_load(raw)
                    except Exception:
                        raise ValueError(f"Unsupported configuration file format: {fname}")

            if overrides and isinstance(overrides, dict):
                if isinstance(config_data, dict):
                    config_data.update(overrides)
                else:
                    # If the config itself is not a dict, cannot apply overrides; ignore
                    pass

            if resolve_env and config_data is not None:
                config_data = _recursively_resolve_env(config_data)

        except (toml.TomlDecodeError, yaml.YAMLError, json.JSONDecodeError, ValueError, FileNotFoundError, OSError) as exc:
            msg = f"Error parsing configuration file '{fname}': {exc}"
            record = logging.LogRecord(name='load_configurations',
                                       level=logging.ERROR,
                                       pathname=fname,
                                       lineno=0,
                                       msg=msg,
                                       args=None,
                                       exc_info=None)
            error_records.append(record)
            config_data = None

        parsed_configs[fname] = config_data

    return parsed_configs, error_records

