    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:  # In case key disappeared between check and deletion
        if default is not __marker:
            return default
        raise

def popitem(self):
        """Remove and return the `(key, value)` pair least recently used."""
        node = self._tail[2]
        if node is self._head:
            raise KeyError('list is empty')
        self._find_lt(node[0])
        self._remove(node)
        return (node[0], node[1])

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        try:
            # Attempt to use the underlying storage's popitem method
            # which should return the most recently used item if it is
            # an OrderedDict or a custom LRU implementation.
            return self._cache.popitem()
        except AttributeError:
            # Fallback to the built‑in dict popitem if no custom
            # implementation is available.
            return dict.popitem(self._cache)
        except KeyError as e:
            # If the container is empty, raise KeyError.
            raise KeyError('dict is empty') from e

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        key, value = dict.popitem(self)
        return key, value
    except KeyError:
        raise KeyError('dict is empty')

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
    except Exception as exc:
        raise RuntimeError("Failed to instantiate _Converter") from exc
    return converter

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # 1. Check for private (JSON) payload
    try:
        body = request.body
        # Ensure body is a string for json.loads
        if isinstance(body, (bytes, bytearray)):
            body_str = body.decode('utf-8', errors='ignore')
        else:
            body_str = str(body)
        data = json.loads(body_str)
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        # Ignore and proceed to next check
        pass

    # 2. Check for public (XML) legacy payload
    try:
        body = request.body
        # lxml.etree.fromstring accepts bytes or str
        if isinstance(body, (bytes, bytearray)):
            body_bytes = body
        else:
            body_bytes = body.encode('utf-8', errors='ignore')
        xml_root = etree.fromstring(body_bytes)
        if xml_root.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        # If parsing fails, it's not a Diaspora request
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request."""
    try:
        # Try to obtain the request path; fall back to META if needed
        path = getattr(request, 'path', None) or request.META.get('PATH_INFO')
    except Exception:
        # If any attribute access fails, we cannot determine the request type
        return False

    # If we have a path, check whether it follows the Matrix API prefix
    if isinstance(path, str) and path.startswith("/_matrix"):
        return True

    # Otherwise, this is not a Matrix request
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    try:
        # If `dt` is not a datetime-like object, we raise a TypeError
        if not hasattr(dt, "strftime"):
            raise TypeError("Expected a datetime object, got %r" % (dt,))
        # Standard ISO‑8601 format used by many D* systems
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception as exc:  # pragma: no cover
        # In case of any unexpected error, re‑raise as a ValueError to keep the
        # function signature clean for callers who expect a plain value
        raise ValueError(f"Could not format datetime {dt!r}") from exc

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        parsed = urllib.parse.urlsplit(url)
        if parsed.scheme not in ("http", "https"):
            return None
        req = urllib.request.Request(url, method="HEAD")
        resp = urllib.request.urlopen(req)
        try:
            return resp.getheader('content-type')
        finally:
            resp.close()
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    if not tag:
        return False
    if len(tag) > 50:
        return False
    for c in tag:
        if not (c.isalnum() or c in ("-", "_")):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Ensure the node is iterable (has children)
    try:
        iterator = iter(node)
    except TypeError:
        raise TypeError('The provided node does not support iteration over children')

    result = {}
    for child in iterator:
        tag = child.tag
        # Get child text; if None, use empty string
        text = child.text if child.text is not None else ''
        # If the same tag occurs multiple times, store a list of texts
        if tag in result:
            current = result[tag]
            if isinstance(current, list):
                current.append(text)
            else:
                result[tag] = [current, text]
        else:
            result[tag] = text
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        # Ensure the base url does not end with a trailing slash
        base = url.rstrip("/")
        # Determine the href for the NodeInfo document
        if document_path:
            # Ensure document_path starts with a slash
            doc_path = document_path if document_path.startswith("/") else "/" + document_path
            href = f"{base}{doc_path}"
        else:
            href = f"{base}/nodeinfo/1"
        # Construct the well-known document as per the spec
        return {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                    "href": href,
                }
            ]
        }
    except Exception:
        # In case of any error (e.g., invalid URL), return None
        return None

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Basic input validation
    if not public_key or not doc or not signature:
        return False

    try:
        import os
        import base64
        from lxml import etree
        import xmlsec
    except Exception:
        # Required libraries are not available
        return False

    # Decode the signature if it is base64-encoded
    try:
        if isinstance(signature, str):
            # Some signatures may be wrapped in <Signature>...</Signature>
            # If the signature string contains XML tags, try to parse it.
            if signature.lstrip().startswith("<"):
                sig_bytes = signature.encode('utf-8')
            else:
                sig_bytes = base64.b64decode(signature)
        else:
            sig_bytes = signature
    except Exception:
        return False

    # Prepare the XML document
    try:
        parser = etree.XMLParser(remove_blank_text=True)
        root = etree.fromstring(doc.encode('utf-8'), parser)
    except Exception:
        return False

    # Load the public key. Accept either a file path or raw PEM string.
    try:
        if hasattr(public_key, "read"):
            # file-like object
            key_data = public_key.read()
        elif os.path.isfile(public_key):
            with open(public_key, "rb") as f:
                key_data = f.read()
        else:
            key_data = public_key.encode('utf-8')
        key = xmlsec.Key.from_memory(key_data, xmlsec.constants.KeyDataFormatPubKeyPem, None)
    except Exception:
        return False

    # Find the Signature node in the XML
    try:
        sig_node = xmlsec.tree.find_node(root, xmlsec.constants.NodeSignature)
        if sig_node is None:
            return False
    except Exception:
        return False

    # Verify the signature
    try:
        ctx = xmlsec.SignatureContext()
        ctx.key = key

        # Register ID attributes commonly used for signed references
        for attr in ("id", "Id", "ID"):
            ctx.register_id(root, attr)

        ctx.register_id(sig_node, "Id")  # sometimes the ID is on the signature itself

        # Perform the verification
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    # Try JSON parsing first (new format)
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict) and "links" in data:
            result["subject"] = data.get("subject")
            for link in data.get("links", []):
                rel = link.get("rel")
                href = link.get("href")
                if rel == "hcard":
                    result["hcard_url"] = href
                elif rel == "lookup":
                    result["lookup_url"] = href
                elif rel == "profile":
                    result["profile_url"] = href
            return result
    except Exception:
        pass  # Fall back to XRD parsing

    # Try XRD parsing (old format)
    try:
        import xml.etree.ElementTree as ET

        root = ET.fromstring(document)
        subject = root.findtext("subject")
        if subject:
            result["subject"] = subject

        for link in root.findall("link"):
            rel = link.get("rel")
            href = link.get("href")
            if rel == "hcard":
                result["hcard_url"] = href
            elif rel == "lookup":
                result["lookup_url"] = href
            elif rel == "profile":
                result["profile_url"] = href

        return result if result else None
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    try:
        url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    except Exception:
        return None
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    if exception:
        return None
    return XRD.parse_xrd(document)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Log the send attempt
    try:
        logger.debug(
            "send_document: url=%s, data=%s, timeout=%s, method=%s",
            url, data, timeout, method
        )
    except NameError:
        # logger may not exist in all contexts; ignore
        pass

    # Prepare headers, respecting any provided in kwargs
    headers = kwargs.pop("headers", {})
    if not isinstance(headers, dict):
        headers = {}

    # Add any additional kwargs
    request_kwargs = {"data": data, "timeout": timeout, "headers": headers}
    request_kwargs.update(kwargs)

    try:
        # Use the specified method; default is POST
        if method.lower() == "post":
            response = requests.post(url, *args, **request_kwargs)
        else:
            # Generic HTTP method handling
            response = requests.request(method.upper(), url, *args, **request_kwargs)

        # Log the response status
        try:
            logger.debug("send_document: response status code %s", response.status_code)
        except NameError:
            pass

        return response.status_code, None
    except requests.exceptions.RequestException as ex:
        # Log the exception
        try:
            logger.debug("send_document: exception %s", ex)
        except NameError:
            pass
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize input to an iterable of directories
        dirs = [settings_dirs] if isinstance(settings_dirs, (str, bytes)) else list(settings_dirs)
        result = []
        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                full_path = os.path.join(directory, fname)
                if not os.path.isfile(full_path):
                    continue
                if spec_option:
                    if fname.endswith(spec_option):
                        result.append(full_path)
                else:
                    result.append(full_path)
        return sorted(result)
    except Exception:
        return []

def ansible_config_manager(cls):
