def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException('No spec content provided')

        # If spec_content is already a Python dict/list, use it directly
        if isinstance(spec_content, (dict, list)):
            data = spec_content
        else:
            try:
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f'YAML parsing error: {exc}')

        if data is None:
            raise IRValidatorException('Parsed YAML is empty or None')

        # Determine required fields; allow subclasses to define their own
        required_fields = getattr(cls, 'REQUIRED_FIELDS', [])
        if not required_fields:
            # Default mandatory fields if none specified
            required_fields = ['name', 'type', 'metadata']

        missing = [field for field in required_fields if field not in data or data[field] in (None, '', [], {})]
        if missing:
            raise IRValidatorException(f'Missing mandatory fields: {", ".join(missing)}')

        return data

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Ensure a file path was provided
        if yaml_file is None:
            raise ValueError("yaml_file argument must be supplied")

        # Load YAML
        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
            if data is None:
                data = {}
        except Exception as e:
            raise IRValidatorException(f"Failed to load YAML file '{yaml_file}': {e}")

        # Check for required fields if defined on the class
        required_fields = getattr(cls, "required_fields", None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing mandatory fields in '{yaml_file}': {', '.join(missing)}"
                )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    def _deep_merge(dest, src):
        for key, val in src.items():
            if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                _deep_merge(dest[key], val)
            else:
                dest[key] = val

    def _resolve_node(name, visited):
        if name not in parser_dict:
            raise KeyError(f"Included group '{name}' not found in parser definitions.")
        node = parser_dict[name]
        # Create a shallow copy to avoid mutating the original until fully merged
        node_copy = dict(node)
        if 'include' in node_copy:
            inc = node_copy.pop('include')
            inc_names = inc if isinstance(inc, (list, tuple)) else [inc]
            merged = {}
            for inc_name in inc_names:
                if inc_name in visited:
                    cycle = ' -> '.join(list(visited) + [inc_name])
                    raise RuntimeError(f"Circular include detected: {cycle}")
                inc_node = _resolve_node(inc_name, visited | {inc_name})
                _deep_merge(merged, inc_node)
            _deep_merge(merged, node_copy)
            return merged
        return node_copy

    # Resolve each parser entry, handling nested includes.
    for key in list(parser_dict.keys()):
        resolved = _resolve_node(key, {key})
        parser_dict[key] = resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        # Skip non-Option types
        if not isinstance(arg, _BaseOpt):
            continue

        name = arg.name

        # Try to obtain a value from the spec first
        value = None
        try:
            value = getattr(self.spec, name)
        except AttributeError:
            # Spec may not expose all attributes directly
            pass

        if value is not None:
            defaults[name] = value
            continue

        # Fall back to the argument's own default if present
        if not isinstance(arg.default, NoDefault):
            defaults[name] = arg.default

        # Handle nested DictOption schemes recursively
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[name] = nested

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Return a mapping of deprecated option names to their replacements.
    # Example: {'old_option': 'new_option', 'legacy_flag': 'modern_flag'}
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Normalize command_name: it must be a non-empty string
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    command_name = command_name.strip()
    if not command_name:
        raise ValueError("command_name cannot be empty")

    # Try to locate the dictionary that holds the option specifications.
    # It can be stored under a few common attribute names.
    option_specs_dict = None
    for attr in ("command_option_specs", "option_specs", "parser_option_specs",
                 "cli_option_specs", "command_options"):
        if hasattr(self, attr):
            option_specs_dict = getattr(self, attr)
            break

    if option_specs_dict is None:
        raise AttributeError("No attribute containing command option specs found on the object")

    # Ensure the dictionary maps command names to iterables (lists, tuples, etc.)
    if not isinstance(option_specs_dict, dict):
        raise TypeError(f"Expected a dict for option specs, got {type(option_specs_dict).__name__}")

    try:
        options = option_specs_dict[command_name]
    except KeyError as exc:
        raise KeyError(f"Command '{command_name}' not found in option specifications") from exc

    # The returned object should be a list; if not, try to convert it.  If conversion fails,
    # fall back to returning the object itself (so callers can handle it).
    if isinstance(options, list):
        return options
    try:
        return list(options)
    except Exception:
        # If options is a non-iterable (e.g., a single option object), return it wrapped in a list.
        return [options] if options is not None else []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")
    # Retrieve the option specification
    try:
        return self._option_spec[command_name][argument_name]
    except KeyError:
        # Option specification not found
        return None
    except Exception as exc:
        # Unexpected error while retrieving the spec
        raise RuntimeError(
            f"Error retrieving option spec for '{command_name}': '{argument_name}'"
        ) from exc

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if args is None:
        raise ValueError("Arguments object cannot be None.")
    # Determine the set of required argument names
    required = getattr(self, 'required', None) or getattr(self, 'required_args', None)
    if not required:
        return True
    missing = []
    for name in required:
        if isinstance(args, dict):
            if name not in args or args[name] is None:
                missing.append(name)
        else:
            try:
                value = getattr(args, name)
                if value is None:
                    missing.append(name)
            except AttributeError:
                missing.append(name)
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Ensure args is a dict for safe lookup; if not, try to convert
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception:
            args = {}

    # Build evaluation environment
    env = {'command_name': command_name}
    env.update(args)

    for opt in options_spec:
        cond = opt.get('required_when')
        if cond:
            try:
                # Evaluate the condition with the prepared environment.
                # The expression is expected to evaluate to a boolean.
                if eval(cond, {}, env):
                    # Use 'name' or 'dest' (common keys in option specs).
                    opt_name = opt.get('name') or opt.get('dest')
                    if opt_name:
                        required.append(opt_name)
            except Exception:
                # If evaluation fails (e.g., syntax error), skip this option.
                continue

    return required

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # args should be a dict (named args) or a list (positional args)
    if not isinstance(args, (dict, list)):
        raise TypeError("args must be a dict or a list")

    # Helper to validate a single argument's length
    def _check_one(arg_name, attr):
        # Determine the specified maximum length
        length_spec = attr.get("max_length") if "max_length" in attr else attr.get("length")
        if length_spec is None:
            # Nothing to check for this argument
            return

        if not isinstance(length_spec, int):
            raise TypeError(f"max_length/length for argument '{arg_name}' must be an integer")

        # Value to test
        value = attr.get("value")
        if value is None:
            # Nothing to check
            return

        # Ensure the value supports len()
        try:
            val_len = len(value)
        except Exception as exc:
            raise TypeError(f"Value of argument '{arg_name}' does not support len()") from exc

        if val_len > length_spec:
            raise ValueError(
                f"Length of argument '{arg_name}' ({val_len}) exceeds allowed maximum ({length_spec})"
            )

    if isinstance(args, dict):
        for arg_name, attr in args.items():
            if not isinstance(attr, dict):
                raise TypeError(f"Attributes for argument '{arg_name}' must be a dict")
            _check_one(arg_name, attr)
    else:  # List case: each item should be a dict with a single key-value pair
        for idx, item in enumerate(args):
            if not isinstance(item, dict):
                raise TypeError(f"List element at index {idx} must be a dict")
            if len(item) != 1:
                raise ValueError(f"List element at index {idx} must contain exactly one argument")
            arg_name, attr = next(iter(item.items()))
            if not isinstance(attr, dict):
                raise TypeError(f"Attributes for argument '{arg_name}' must be a dict")
            _check_one(arg_name, attr)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # No choices defined, nothing to validate
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        return

    for arg_name, value in args.items():
        if arg_name in self.choices:
            allowed = self.choices[arg_name]
            # Ensure allowed is an iterable of accepted values
            if not hasattr(allowed, "__contains__"):
                raise TypeError(f"Allowed choices for argument '{arg_name}' must be an iterable, got {type(allowed).__name__}")
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': '{value}'. "
                    f"Allowed choices are: {tuple(allowed)}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable")

    # Retrieve minimum and maximum from the instance if set
    min_ = getattr(self, 'min_', None)
    max_ = getattr(self, 'max_', None)

    # Validate that at least one bound is provided
    if min_ is None and max_ is None:
        raise ValueError("minimum and/or maximum value must be defined")

    # If both bounds exist, ensure min <= max
    if min_ is not None and max_ is not None and min_ > max_:
        raise ValueError("maximum value must be greater than or equal to minimum")

    # Iterate over all values and enforce bounds
    for idx, val in enumerate(args):
        # Ensure numeric comparison
        try:
            num_val = float(val)
        except (TypeError, ValueError):
            raise TypeError(f"argument at position {idx} is not numeric: {val!r}")

        if min_ is not None and num_val < min_:
            raise ValueError(
                f"argument at position {idx} ({num_val}) below minimum {min_}"
            )
        if max_ is not None and num_val > max_:
            raise ValueError(
                f"argument at position {idx} ({num_val}) above maximum {max_}"
            )

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Attempt to construct the complex type using a factory if provided
    try:
        factory = spec_option.get('factory')
        if factory is not None:
            # Resolve the factory if it is specified as a string
            if isinstance(factory, str):
                factory = self.load_name(factory)
            # Separate positional and keyword arguments for the factory
            args = spec_option.get('args', [])
            kwargs = spec_option.get('kwargs', {})
            complex_type = factory(*args, **kwargs)
        else:
            # No factory, construct a simple namespace or dictionary
            complex_type = type(
                type_name,
                (object,),
                {
                    'subcommand': subcommand,
                    'option_name': option_name,
                    **spec_option
                }
            )()
    except Exception as exc:
        # Wrap any exception in a more descriptive error
        raise ValueError(
            f"Failed to create complex type '{type_name}' for subcommand '{subcommand}': {exc}"
        ) from exc

    return complex_type

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list")
    for extra in extra_vars:
        if isinstance(extra, dict):
            vars_dict.update(extra)
        else:
            raise TypeError("Each element of extra_vars must be a dict")
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :returns: The modified values_dict with values casted to their intended types.
    """
    # Define any concrete type mappings per parser if known.
    # This is optional; generic conversion will be applied otherwise.
    type_map = {
        # Example: 'main': {'count': int, 'verbose': bool},
        # Add additional parser-specific mappings here.
    }

    # Retrieve the mapping for the given parser name, if any.
    parser_map = type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        # If the parser has an explicit type for this key, use it.
        if key in parser_map:
            target_type = parser_map[key]
            try:
                if target_type is bool:
                    if isinstance(val, str):
                        values_dict[key] = val.lower() in ('true', '1', 'yes')
                    else:
                        values_dict[key] = bool(val)
                else:
                    values_dict[key] = target_type(val)
            except Exception:
                # If conversion fails, leave the original value unchanged.
                pass
        else:
            # Generic conversion attempts for values that remain strings.
            if isinstance(val, str):
                lower_val = val.lower()
                # Boolean
                if lower_val in ('true', 'false'):
                    values_dict[key] = lower_val == 'true'
                else:
                    # Integer or float
                    try:
                        if '.' in val:
                            values_dict[key] = float(val)
                        else:
                            values_dict[key] = int(val)
                    except ValueError:
                        # Attempt JSON decode
                        try:
                            import json
                            values_dict[key] = json.loads(val)
                        except Exception:
                            # Leave string untouched if all else fails.
                            pass
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import io

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # Flatten list items with index keys
                for idx, item in enumerate(v):
                    if isinstance(item, dict):
                        items.update(_flatten(item, f"{new_key}{sep}{idx}", sep=sep))
                    else:
                        items[f"{new_key}{sep}{idx}"] = item
            else:
                items[new_key] = v
        return items

    flat_spec = {}
    if not plugin_dir:
        return flat_spec
    # Ensure plugin_dir is a string path
    path = str(plugin_dir)
    if not os.path.isdir(path):
        return flat_spec

    # Define possible spec filenames and order of preference
    spec_filenames = ["plugin.json", "plugin.yml", "plugin.yaml"]
    spec_content = None

    for filename in spec_filenames:
        spec_path = os.path.join(path, filename)
        if os.path.isfile(spec_path):
            try:
                with io.open(spec_path, "r", encoding="utf-8") as f:
                    if filename.endswith(".json"):
                        spec_content = json.load(f)
                    else:  # yaml
                        try:
                            import yaml
                        except ImportError:
                            # Cannot read YAML without PyYAML, skip
                            continue
                        spec_content = yaml.safe_load(f)
                break  # stop after first successfully loaded spec
            except Exception:
                # Skip this file if any error occurs
                continue

    if isinstance(spec_content, dict):
        flat_spec = _flatten(spec_content)

    return flat_spec

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, 'config_environment_variable', 'CONFIG_PATH')
    try:
        if env_var not in os.environ:
            if not hasattr(self, 'config_path'):
                raise AttributeError("Instance missing attribute 'config_path'")
            os.environ[env_var] = str(self.config_path)
    except Exception as exc:
        logger.exception("Failed to set config environment variable %s: %s", env_var, exc)

def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    """
    import os

    # Validate inputs
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"'path' must be a string or bytes, got {type(path).__name__}")
    if not isinstance(root, (str, bytes)):
        raise TypeError(f"'root' must be a string or bytes, got {type(root).__name__}")

    try:
        abs_path = os.path.abspath(path)
        abs_root = os.path.abspath(root)
    except Exception as exc:
        raise ValueError(f"Failed to resolve absolute paths: {exc}") from exc

    # Normalize separator handling
    sep = os.sep
    root_with_sep = abs_root.rstrip(sep) + sep

    if abs_path == abs_root:
        # The path is exactly the root; return empty string
        return os.path.relpath(abs_path, abs_root)
    elif abs_path.startswith(root_with_sep):
        stripped = abs_path[len(root_with_sep):]
        # Ensure we strip any leading separator that may remain
        stripped = stripped.lstrip(sep)
        return stripped
    else:
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
